"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[2543],{82543:e=>{e.exports=JSON.parse('{"slug":"inflyaciya-oktyabr-2026-tarify-zhkh","locale":"es","title":"La inflaci\xf3n interanual pasa del 6,26% al 7,17% en una semana tras subir los servicios p\xfablicos","description":"Del 29 de septiembre al 5 de octubre de 2026 los precios suben un 0,96% y la inflaci\xf3n interanual llega al 7,17%. Cu\xe1nto aportan las tarifas y por qu\xe9 salta el indicador anual.","blocks":[{"id":"b001","kind":"paragraph","text":"Del 29 de septiembre al 5 de octubre de 2026 los precios rusos subieron un 0,96%, frente al 0,12% previo. La actualizaci\xf3n de servicios p\xfablicos del 1 de octubre aport\xf3 0,75 puntos porcentuales. El saneamiento subi\xf3 un 17,1%; el agua fr\xeda, un 15,3%; la caliente, un 14,2%; la calefacci\xf3n, un 12,7%; y la electricidad, un 12%. La factura total sube menos, un 9,9% de media nacional: el \xedndice del Gobierno limita el total, no cada servicio. Mosc\xfa llega al 15%, San Petersburgo al 14,6% y el m\xe1ximo de Stavropol al 22%."},{"id":"b002","kind":"paragraph","text":"Sin servicios p\xfablicos, los precios subieron un 0,21% semanal, m\xe1s que toda la cesta la semana anterior. Los alimentos aumentaron un 0,17%: frutas y verduras bajaron un 0,57% y el resto subi\xf3 un 0,24%. Los huevos aumentaron un 2,2%; las conservas c\xe1rnicas, un 1,6%; y el trigo sarraceno, un 1%. Los bienes no alimentarios sumaron un 0,13%; los tel\xe9fonos, un 1,1%; y los televisores, un 1%."},{"id":"b003","kind":"paragraph","text":"La inflaci\xf3n interanual pas\xf3 del 6,26% al 7,17%. Imagina una familia que paga el seguro del coche una vez al a\xf1o: antes en julio y ahora en octubre. En octubre el gasto parece mayor frente al a\xf1o anterior, aunque el total anual sea id\xe9ntico. Las tarifas subieron el 1 de julio de 2025 un 11,9%; en 2026, un 1,7% en enero y un 9,9% en octubre, aproximadamente un 11,8% conjunto. Como en octubre de 2025 no cambiaron, el salto actual entra entero en la comparaci\xf3n anual. Es el efecto base. Desde 2027 volver\xe1n a subir en julio."},{"id":"b004","kind":"paragraph","text":"Si los servicios costaban 6 mil rublos mensuales, la subida media ronda 600 rublos y en Mosc\xfa, hasta 900. No incluye mantenimiento del edificio ni grandes reparaciones. Es un gasto que no se puede posponer. Los dep\xf3sitos a\xfan superan los precios: el promedio de m\xe1ximos de los 10 mayores bancos al cierre de septiembre era del 13,05%, frente al 7,17% de inflaci\xf3n interanual."},{"id":"b005","kind":"paragraph","text":"El Banco de Rusia prev\xe9 un 6–7% de inflaci\xf3n en 2026. Desde enero, los precios llevan un 5,94%, y la inflaci\xf3n interanual seg\xfan su metodolog\xeda, del 7,08%, ya supera el techo previsto para el cierre. Kirill Tremasov hab\xeda anticipado en septiembre unos 0,7 puntos por tarifas; para la decisi\xf3n del 23 de octubre importan m\xe1s los dem\xe1s precios. Un 0,21% semanal durante todo el a\xf1o dar\xeda m\xe1s del 11%. El 11 de septiembre se mantuvo el tipo en el 14%, advirtiendo que predominaban los riesgos inflacionarios."},{"id":"b006","kind":"paragraph","text":"Una semana prueba poco. Rosstat publica septiembre el 9 de octubre y la siguiente semana el 14. Si el crecimiento sin tarifas vuelve al 0,1% semanal, ser\xe1 un salto puntual. Si ronda el 0,2%, habr\xe1 menos motivos para bajar el tipo: los cr\xe9ditos seguir\xe1n caros y los dep\xf3sitos remunerados durante m\xe1s tiempo."},{"id":"b007","kind":"heading","text":"\xbfPor qu\xe9 la inflaci\xf3n semanal alcanz\xf3 el 0,96% a principios de octubre de 2026?"},{"id":"b008","kind":"paragraph","text":"Las tarifas de servicios p\xfablicos subieron desde el 1 de octubre un 9,9% de media. Aportaron 0,75 puntos de los 0,96%. Sin ellas, los precios crecieron un 0,21% semanal."},{"id":"b009","kind":"heading","text":"\xbfPor qu\xe9 la inflaci\xf3n anual salt\xf3 del 6,26% al 7,17% en una semana?"},{"id":"b010","kind":"paragraph","text":"Por el efecto base. Las tarifas subieron el 1 de julio de 2025 un 11,9%; en 2026, un 1,7% en enero y un 9,9% desde el 1 de octubre. En octubre de 2025 no variaron, por lo que la comparaci\xf3n anual salta aunque el crecimiento total sea parecido, alrededor del 11,8%."},{"id":"b011","kind":"heading","text":"\xbfCu\xe1nto subieron las facturas desde el 1 de octubre de 2026?"},{"id":"b012","kind":"paragraph","text":"Los servicios subieron un 9,9% de media, hasta el 15% en Mosc\xfa, el 14,6% en San Petersburgo y el 22% en Stavropol. No incluye mantenimiento ni grandes reparaciones. Por servicio, el saneamiento subi\xf3 un 17,1%; el agua fr\xeda, un 15,3%; la calefacci\xf3n, un 12,7%; y la electricidad, un 12%."}],"sources":[{"label":"Inflaci\xf3n rusa del 29 de septiembre al 5 de octubre","url":"https://www.vedomosti.ru/economics/news/2026/10/07/1235202-inflyatsiya-v-rossii"},{"label":"Econom\xeda atribuye 0,75 puntos de inflaci\xf3n semanal a las tarifas p\xfablicas","url":"https://www.vedomosti.ru/economics/news/2026/10/07/1235205-minek-otsenil-vklad-indeksatsii"},{"label":"Las tarifas p\xfablicas aportan 0,75 puntos a la inflaci\xf3n semanal","url":"https://www.interfax.ru/business/1120937"},{"label":"Econom\xeda sit\xfaa la inflaci\xf3n anual del 29 de septiembre al 5 de octubre en el 7,17%","url":"https://www.bfm.ru/news/620178"},{"label":"Servicios p\xfablicos desde el 1 de octubre de 2026: cambios en las facturas","url":"https://finuslugi.ru/navigator/kak-ehto-rabotaet/stat_tarify-zhkkh-s-1-oktyabrya-2026-goda-kak-izmenyatsya-platezhi"},{"label":"La inflaci\xf3n semanal salta un 0,96% por las tarifas","url":"https://ru.themoscowtimes.com/2026/10/07/nedelnaya-inflyatsiya-v-rf-podskochila-na-096-iz-za-indeksatsii-tarifov-a208051"},{"label":"El Banco de Rusia eleva su previsi\xf3n de inflaci\xf3n para 2026","url":"https://www.kommersant.ru/doc/8843971"},{"label":"El tipo oficial se mantiene en el 14% el 11 de septiembre de 2026","url":"https://finance.mail.ru/article/stavka-centrobanka-neizmenna-14-kak-reshenie-soveta-direktorov-cb-povliyaet-na-ekonomiku-69227357/"},{"label":"El promedio de tipos m\xe1ximos de diez bancos sube al 13,05%","url":"https://ria.ru/20261001/bank-2121443529.html"}],"sourceBodySha256":"2123f3266d3346c5a40c0ca0051d02fcbfdc4a0c1b55fe5c397edea22f975b4d"}')}}]);